const item=$input.item.json;
const cfg=item.__cfg||{};
if(!cfg.static_base_id||!cfg.manus_project_id||!cfg.skill_name){throw new Error('Client config missing on record '+(item.id||'(no id)')+'. Aborting rather than submitting to the wrong client.');}
const sourceName=item['Source Name']||'';
const fileUrl=(item['Ebook_Source_File_URL']||'').trim();
const existingNotes=item['Notes']||'';
const STAGE_TAG='EBOOK LINKEDIN POSTS (skill)';
const sep='==============================';
const blockRe=new RegExp('\\n*'+sep+'\\n'+STAGE_TAG.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'[\\s\\S]*?(?=(\\n'+sep+'\\n)|$)','g');
const notesBase=existingNotes.replace(blockRe,'').trim();
return{json:{record_id:item.id||'',source_name:sourceName,topic:sourceName,ebook_file_url:fileUrl,client:cfg.client_name||'',notes_base:notesBase,stage_tag:STAGE_TAG,sep,has_file:/^https?:\/\/\S+$/i.test(fileUrl),cfg}};

const resp=$input.item.json;
const ctx=$('6. Build Manus Message').item.json;
const cfg=ctx.cfg||{};
const skills=(resp&&resp.data)?resp.data:[];
const target=(cfg.skill_name||'').toLowerCase().trim();
const fallbacks=(cfg.skill_fallback||'').split(',').map(s=>s.trim().toLowerCase()).filter(Boolean);
let hit=skills.find(s=>(s.name||'').toLowerCase()===target);
if(!hit&&target)hit=skills.find(s=>(s.name||'').toLowerCase().includes(target));
if(!hit)for(const f of fallbacks){hit=skills.find(s=>(s.name||'').toLowerCase()===f)||skills.find(s=>(s.name||'').toLowerCase().includes(f));if(hit)break;}
if(!hit||!hit.id){
  const available=skills.map(s=>s.name).filter(Boolean);
  throw new Error('Skill not resolved for client '+(cfg.client_name||'(unknown)')+'. Wanted: "'+(cfg.skill_name||'(none)')+'". Manus project: '+(cfg.manus_project_id||'(none)')+'. skill.list returned '+available.length+' skill(s): '+(available.length?available.join(', '):'(empty)')+'. Refusing to submit without an explicit skill.');
}
return{json:{...ctx,resolved_skill_id:hit.id,resolved_skill_name:hit.name||'',skill_resolve_error:''}};

