const r=$input.item.json;
const ctx=$('6c. Pick Skill').item.json;
const taskId=r.task_id||r.id||(r.data&&(r.data.task_id||r.data.id))||'';
return{json:{...ctx,manus_task_id:taskId,manus_task_url:r.task_url||'',manus_has_task:!!taskId,manus_error:taskId?'':JSON.stringify(r).substring(0,200)}};

const d=$input.item.json;
const recordId=d.record_id||'';
const nameSlug=(d.source_name||'ebook-posts').toLowerCase().replace(/[^\w\s-]/g,'').replace(/\s+/g,'-').replace(/-+/g,'-').substring(0,50).replace(/^-|-$/g,'');
const subfolderName=`${recordId}_${nameSlug}_linkedin-posts`;
return{json:{...d,subfolder_name:subfolderName}};

const folderResp=$input.item.json;
const prev=$('4c. Prepare Subfolder Name').item.json;
const subFolderId=folderResp.id||'';
const driveFolderUrl=subFolderId?`https://drive.google.com/drive/folders/${subFolderId}`:'';
return{json:{...prev,sub_folder_id:subFolderId,drive_folder_url:driveFolderUrl,folder_error:subFolderId?'':'Folder creation failed: '+JSON.stringify(folderResp)}};

const OUTPUT_TYPE = 'ebook-linkedin';
const clients = $('0a. Load Clients').all().map(i => i.json);
const outputs = $input.all().map(i => i.json);
const out = [];
for (const c of clients) {
  const name = c['Client_Name'];
  if (!name) continue;
  if (c['Static_Enabled'] !== true) continue;
  const row = outputs.find(o => o['Key'] === name + '::' + OUTPUT_TYPE);
  if (!row) continue;
  if (row['Enabled'] !== true) continue;
  if (!c['Static_Base_ID'] || !row['Drive_Folder_ID'] || !row['Manus_Project_ID'] || !row['Skill_Name']) continue;
  out.push({ json: {
    client_name: name,
    static_base_id: c['Static_Base_ID'],
    brand_name: c['Brand_Name'] || name,
    timezone: c['Timezone'] || 'Asia/Manila',
    drive_folder_id: row['Drive_Folder_ID'],
    manus_project_id: row['Manus_Project_ID'],
    skill_name: row['Skill_Name'],
    skill_fallback: row['Skill_Fallback'] || ''
  }});
}
return out;

const loop = $('0d. Client Loop');
let cfg = null;
try { cfg = loop.item.json; } catch (e) { cfg = null; }
if (!cfg || !cfg.static_base_id) { throw new Error('Could not resolve client config for this iteration. Refusing to run with the wrong client.'); }
return { json: { ...$input.item.json, __cfg: cfg } };
